import sys
import os
import re
import subprocess
import time
import json
from themes_data import THEMES
from descriptions import DESCRIPTIONS

VERSION = "i3-style 1.0"

def print_help():
    print("""i3-style 1.0
Make your i3 config a bit more stylish

USAGE:
    executable [FLAGS] [OPTIONS] [theme]

FLAGS:
    -h, --help        Prints help information
    -l, --list-all    Print a list of all available themes
    -r, --reload      Apply the theme by reloading the config
    -s, --save        Set the output file to the path of the input file
    -V, --version     Prints version information

OPTIONS:
    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.
    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>
    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others
                             [default: ]

ARGS:
    <theme>    The theme to use""")

def list_all():
    print("\nAvailable themes:\n")
    for name in DESCRIPTIONS:
        print(f"  {name:<18} - {DESCRIPTIONS[name]}")

def get_default_config():
    paths = [
        os.path.expanduser("~/.i3/config"),
        os.path.expanduser("~/.config/i3/config")
    ]
    for p in paths:
        if os.path.exists(p):
            return p
    return paths[1] # Default to ~/.config/i3/config if none exist

def validate_config(config_path):
    try:
        res = subprocess.run(["i3", "-C", "-c", config_path], capture_output=True)
        if res.returncode != 0:
            return False, res.stderr.decode()
        return True, ""
    except FileNotFoundError:
        return False, f"Could not validate config with `i3 -C -c {config_path}` (is i3 in the PATH?) No such file or directory (os error 2)"

def reload_i3():
    subprocess.run(["i3-msg", "reload"], capture_output=True)

def to_theme(config_path):
    if not os.path.exists(config_path):
        print(f"Error: Config file {config_path} does not exist.")
        sys.exit(1)

    ok, err = validate_config(config_path)
    if not ok:
        print(err, file=sys.stderr)
        sys.exit(1)

    with open(config_path, "r") as f:
        lines = f.readlines()

    window_colors = {}
    bar_colors = {}

    # Simple parsing for to-theme
    in_bar = False
    in_colors = False
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"): continue

        if line.startswith("bar {"): in_bar = True
        elif in_bar and line.startswith("colors {"): in_colors = True
        elif line.startswith("}"):
            if in_colors: in_colors = False
