    def resolve(v):
        if v in colors_def: return colors_def[v]
        return v

    res = {"window_colors": {}, "bar_colors": {}}
    for key in ["focused", "focused_inactive", "unfocused", "urgent"]:
        w = []
        for prop in ["border", "background", "text", "indicator"]:
