    for key in ["focused_workspace", "active_workspace", "inactive_workspace", "urgent_workspace", "binding_mode"]:
        w = []
        for prop in ["border", "background", "text"]:
            val = get_val("bar_colors", key, prop)
            if val: w.append(resolve(val))
        if w: res["bar_colors"][key] = w
    return res

