    args = sys.argv[1:]
    if not args:
        print("USAGE:\n    executable [FLAGS] [OPTIONS] [theme]\n\nSelect a theme as the first argument. Use `--list-all` to see the themes.")
        sys.exit(1)

    flags = {"reload": False, "save": False}
    options = {"config": None, "output": None, "to-theme": None}
    theme = None

