        elif arg in ["-c", "--config"]:
            i += 1; options["config"] = args[i]
        elif arg.startswith("--config="): options["config"] = arg.split("=")[1]
        elif arg in ["-o", "--output"]:
            i += 1; options["output"] = args[i]
        elif arg.startswith("--output="): options["output"] = arg.split("=")[1]
        elif arg in ["-t", "--to-theme"]:
            i += 1; options["to-theme"] = args[i]
        elif arg.startswith("--to-theme="): options["to-theme"] = arg.split("=")[1]
