    config_path = options["config"] or get_default_config()
    output_path = options["output"]
    if flags["save"]: output_path = config_path

    apply_theme(theme_data, config_path, output_path or "-")
    if flags["reload"]: reload_i3()

if __name__ == "__main__":
    main()
