    prefix = line[:first_color_match.start()]
    # All hex colors in original line
    orig_colors = re.findall(r"#[0-9a-fA-F]{6}", line)

    # Result colors: Theme colors + any remaining original colors (if any?)
    # Wait, my test_trailing showed: T0 T1 T2 O2.
    # This means it replaced O0, O1, O2 with T0, T1, T2.
    # And then it somehow kept O2? No, that was O3? No.
    # Let's use the rule: replace up to len(new_colors) colors.

    res_colors = list(new_colors)
    if len(orig_colors) > len(new_colors):
        # This is where the "keep original" logic comes in.
        # In my test_trailing: O=5, T=3, Result=4.
        # This is very specific. Let's just do:
        res_colors.extend(orig_colors[len(new_colors):])

    return f"{prefix}{' '.join(res_colors)}\n"

