            val_match = re.search(fr"^\s*{subkey}:\s*(\S+)", sk_content, re.M)
            return val_match.group(1) if val_match else None
        else:
            val_match = re.search(fr"^\s*{key}:\s*(\S+)", s_content, re.M)
            return val_match.group(1) if val_match else None

    colors_def = {}
    c_match = re.search(r"^colors:\s*(.*?)(?=\n\S|$)", content, re.M | re.S)
    if c_match:
        for line in c_match.group(1).splitlines():
            line = line.strip()
            if ":" in line:
                k, v = line.split(":")
                v = v.strip().strip('"')
                colors_def[k.strip()] = v

    def resolve(v):
        if v in colors_def: return colors_def[v]
        return v

