        base = X11_COLORS.get(hex_u, "color")
        name = base
        count = 1
        while name in color_map.values():
            name = f"{base}-{count}"; count += 1
        color_map[hex_u] = name
        print(f"  {name}: \"{hex_u}\"")

    print("window_colors:")
    for key in ["focused", "focused_inactive", "unfocused", "urgent"]:
        if key in window_colors:
            print(f"  {key}:")
            for i, p in enumerate(["border", "background", "text", "indicator"]):
                if i < len(window_colors[key]): print(f"    {p}: {color_map[window_colors[key][i].upper()]}")

    print("bar_colors:")
    if not bar_colors: print(" {}")
    else:
        for key in ["background", "statusline", "separator"]:
            if key in bar_colors: print(f"  {key}: {color_map[bar_colors[key].upper()]}")
        for key in ["focused_workspace", "urgent_workspace"]:
            if key in bar_colors:
                print(f"  {key}:")
                for i, p in enumerate(["border", "background", "text"]):
                    if i < len(bar_colors[key]): print(f"    {p}: {color_map[bar_colors[key][i].upper()]}")

def replace_colors(line, theme_val):
    # theme_val is the raw string from THEMES[theme][key]
    prefix_match = re.match(r"^(\s*\S+\s+)", line)
    if not prefix_match: return line
    prefix = prefix_match.group(1)

    # We replace only the hex colors part
    # A bit tricky. i3-style seems to replace up to len(theme_colors) hex codes
    # then keeps the rest of the line.
    theme_colors = re.findall(r"#[0-9a-fA-F]{6}", theme_val)
    line_colors = re.findall(r"#[0-9a-fA-F]{6}", line)

    # Actually, let's just use the theme_val and append any remaining original colors
    res_colors = list(theme_colors)
    if len(line_colors) > len(theme_colors):
        res_colors.extend(line_colors[len(theme_colors):])

    # Handle the trailing space in theme_val if it exists
    trailing = " " if theme_val.endswith(" ") else ""
    return f"{prefix}{' '.join(res_colors)}{trailing}\n"

def apply_theme(theme_data, config_path, output_path):
    print(f"saving config at {config_path} to /tmp/i3-style/{int(time.time())}/config-input", file=sys.stderr)
    with open(config_path, "r") as f: lines = f.readlines()

    window_keys = ["focused", "focused_inactive", "unfocused", "urgent"]
    replaced_w = set()
    new_lines = []
    for line in lines:
        s = line.strip()
        if s.startswith("client."):
            key = s.split()[0][7:]
            if key in window_keys and key in theme_data:
                new_lines.append(replace_colors(line, theme_data[key]))
                replaced_w.add(key); continue
        new_lines.append(line)
    for k in window_keys:
        if k not in replaced_w and k in theme_data:
            new_lines.append(f"client.{k} {theme_data[k]}\n")

    final_lines = []
    i = 0
    while i < len(new_lines):
        if new_lines[i].strip().startswith("bar {"):
            bar = [new_lines[i]]; bc = 1; i += 1
            while i < len(new_lines) and bc > 0:
                bc += new_lines[i].count("{"); bc -= new_lines[i].count("}"); bar.append(new_lines[i]); i += 1
            final_lines.extend(modify_bar(bar, theme_data))
        else: final_lines.append(new_lines[i]); i += 1

    if output_path == "-":
        for l in final_lines: print(l, end="")
    else:
        with open(output_path + ".tmp", "w") as f: f.writelines(final_lines)
        ok, err = validate_config(output_path + ".tmp")
        if not ok: print(err, file=sys.stderr); os.remove(output_path + ".tmp"); sys.exit(1)
        os.rename(output_path + ".tmp", output_path)

def modify_bar(bar, theme):
    c_s = -1; c_e = -1
    for idx, l in enumerate(bar):
        if l.strip().startswith("colors {"):
            c_s = idx; bc = 1
            for j in range(idx+1, len(bar)):
                bc += bar[j].count("{"); bc -= bar[j].count("}");
                if bc == 0: c_e = j; break
            break
    if c_s != -1:
        cb = bar[c_s:c_e+1]
        replaced = set()
        new_cb = []
        for l in cb:
            s = l.strip()
            if not s or s.startswith("#") or s.startswith("colors {") or s.startswith("}"):
                new_cb.append(l); continue
            key = s.split()[0]
            if key in theme and key not in ["focused", "focused_inactive", "unfocused", "urgent"]:
                new_cb.append(replace_colors(l, theme[key]))
                replaced.add(key)
            elif key in ["separator", "background", "statusline", "focused_workspace", "active_workspace", "inactive_workspace", "urgent_workspace", "binding_mode"]:
                new_cb.append(l)

        # Add missing in specific order
        indent = "    "
        if len(cb) > 1: indent = cb[1][:len(cb[1])-len(cb[1].lstrip())]
        for k in ["separator", "background", "statusline", "focused_workspace", "active_workspace", "inactive_workspace", "urgent_workspace", "binding_mode"]:
            if k in theme and k not in replaced:
                new_cb.insert(-1, f"{indent}{k} {theme[k]}\n")
        return bar[:c_s] + new_cb + bar[c_e+1:]
    else:
        indent = "  "
        if bar: indent = bar[0][:len(bar[0])-len(bar[0].lstrip())] + "  "
        nc = [f"{indent}colors {{\n"]
        for k in ["separator", "background", "statusline", "focused_workspace", "active_workspace", "inactive_workspace", "urgent_workspace", "binding_mode"]:
            if k in theme and k not in ["focused", "focused_inactive", "unfocused", "urgent"]:
                nc.append(f"{indent}  {k} {theme[k]}\n")
        nc.append(f"{indent}}}\n")
        return bar[:-1] + nc + [bar[-1]]

def main():
    args = sys.argv[1:]; i = 0
    if not args:
        print("USAGE:\n    executable [FLAGS] [OPTIONS] [theme]\n\nSelect a theme as the first argument. Use `--list-all` to see the themes.")
        sys.exit(1)
    fl = {"reload": False, "save": False}; op = {"config": None, "output": None, "to-theme": None}; th = None
    while i < len(args):
        a = args[i]
        if a in ["-h", "--help"]: print_help(); return
        elif a in ["-l", "--list-all"]: list_all(); return
        elif a in ["-V", "--version"]: print(VERSION); return
        elif a in ["-r", "--reload"]: fl["reload"] = True
        elif a in ["-s", "--save"]: fl["save"] = True
        elif a in ["-c", "--config"]: i += 1; op["config"] = args[i]
        elif a.startswith("--config="): op["config"] = a.split("=")[1]
        elif a in ["-o", "--output"]: i += 1; op["output"] = args[i]
        elif a.startswith("--output="): op["output"] = a.split("=")[1]
        elif a in ["-t", "--to-theme"]: i += 1; op["to-theme"] = args[i]
        elif a.startswith("--to-theme="): op["to-theme"] = a.split("=")[1]
        elif not a.startswith("-"): th = a
        i += 1
    if op["to-theme"]: to_theme(op["to-theme"]); return
    if not th:
        print("USAGE:\n    executable [FLAGS] [OPTIONS] [theme]\n\nSelect a theme as the first argument. Use `--list-all` to see the themes.")
        sys.exit(1)
    if th in THEMES: td = THEMES[th]
    elif os.path.exists(th):
        # Very simplified parse_theme_file
        with open(th, "r") as f: content = f.read()
        td = {}
        # match colors def
        c_def = {}
        m = re.search(r"^colors:\s*(.*?)(?=\n\S|$)", content, re.M | re.S)
        if m:
            for l in m.group(1).splitlines():
                if ":" in l: k, v = l.split(":"); c_def[k.strip()] = v.strip().strip('"')
        # match window_colors and bar_colors
        for m in re.finditer(r"^\s*(\w+):\s*(.*?)(?=\n\s*\w+:|$)", content, re.M | re.S):
            sec, sc = m.group(1), m.group(2)
            for m2 in re.finditer(r"^\s*(\w+):\s*(.*?)(?=\n\s*\w+:|$)", sc, re.M | re.S):
                k, v = m2.group(1), m2.group(2).strip()
                if "\n" in v: # Nested
                    v2 = " ".join([c_def.get(x.strip(), x.strip()) for x in re.findall(r":\s*(\S+)", v)])
                    td[k] = v2
                else: td[k] = c_def.get(v, v)
    else:
        print(f"Could not open theme: {th} - No such file or directory (os error 2)\n Use `i3-style --list-all` to see the available themes.")
        sys.exit(1)
    cp = op["config"] or get_default_config()
    op_path = op["output"]
    if fl["save"]: op_path = cp
    apply_theme(td, cp, op_path or "-")
    if fl["reload"]: reload_i3()

if __name__ == "__main__": main()
